/**
 * Pure tests for the triage `decision` port.
 *
 * The oracle fixture is generated by
 * `apps/crq-python/triage_decision_vectors.py` from the PRODUCTION Python
 * `crq_repair.triage.decision`. Each case replays the recorded repository
 * facts (resolve answers, raw git stdout bytes, lineage results, entry blobs;
 * any of which may instead raise a named Python exception) and compares the
 * decision tuple and the exact repository read order. Where Python raises
 * uncaught, the port must refuse (`KeyError`/`AttributeError`) or propagate the
 * repository's own failure unchanged.
 *
 * No process, filesystem write, clock, provider or network participates.
 */
import { readFileSync } from 'node:fs';
import { describe, expect, test } from 'vitest';
import { parseJsonValue, toPlainJson, type JsonValue } from '../../../src/policy/crq/jsonValue.js';
import {
  TriageDecisionRefusal,
  TriageGitFailure,
  triageDecision,
  type TriageDecisionRepo,
} from '../../../src/policy/crq/triageDecision.js';

type Fact = { result?: string | null; hex?: string; blob?: string; raises?: string };

interface DecisionCase {
  name: string;
  row_json: string;
  report_json: string;
  resolve: Record<string, Fact>;
  git: Record<string, Fact>;
  lineage: Record<string, Fact>;
  entries: Record<string, Fact>;
  ts_refuses: boolean;
  expected: {
    calls: unknown[][];
    status?: string;
    reason?: string;
    extras_json?: string;
    raises?: string;
    injected?: boolean;
  };
}

const fixture = JSON.parse(
  readFileSync(
    new URL('../../../apps/crq-python/fixtures/crq-triage-decision/cases.json', import.meta.url),
    'utf8',
  ),
) as { tip: string; cases: DecisionCase[] };

/** Python `json.dumps` of the scalar/empty-container values the vectors key on. */
function key(value: JsonValue | undefined): string {
  return JSON.stringify(toPlainJson(value ?? null));
}

function answer(table: Record<string, Fact>, name: string, what: string): Fact {
  const fact = table[name];
  if (fact === undefined) throw new Error(`unexpected ${what}: ${name}`);
  if (fact.raises !== undefined) throw new TriageGitFailure(fact.raises);
  return fact;
}

function fakeRepo(spec: DecisionCase, calls: unknown[][]): TriageDecisionRepo {
  return {
    resolve(value) {
      // Record the raw argument: a missing key must arrive as null (Python None), never undefined.
      calls.push(['resolve', value === undefined ? '<undefined>' : (toPlainJson(value) as string)]);
      return answer(spec.resolve, key(value), 'resolve').result as string;
    },
    git(...args) {
      calls.push(['git', ...args]);
      const hex = answer(spec.git, JSON.stringify(args).replaceAll(',', ', '), 'git').hex as string;
      return Uint8Array.from(Buffer.from(hex, 'hex'));
    },
    lineage(target, commit, path) {
      calls.push(['lineage', target, commit, path]);
      return (
        answer(
          spec.lineage,
          JSON.stringify([target, commit, path]).replaceAll(',', ', '),
          'lineage',
        ).result ?? null
      );
    },
    entryBlob(tip, path) {
      calls.push(['entries', tip]);
      calls.push(['entry', key(path)]);
      const fact = spec.entries[key(path)];
      if (fact === undefined) throw new TriageGitFailure('KeyError');
      if (fact.raises !== undefined) throw new TriageGitFailure(fact.raises);
      return fact.blob as string;
    },
  };
}

describe('triageDecision against the Python oracle', () => {
  test('the fixture is large and covers refusals', () => {
    expect(fixture.cases.length).toBeGreaterThan(150);
    expect(fixture.cases.some((item) => item.ts_refuses)).toBe(true);
  });

  for (const item of fixture.cases) {
    test(item.name, () => {
      const calls: unknown[][] = [];
      const repo = fakeRepo(item, calls);
      const row = parseJsonValue(item.row_json);
      const report = parseJsonValue(item.report_json);
      const run = (): ReturnType<typeof triageDecision> =>
        triageDecision(repo, row, fixture.tip, report);
      const expected = item.expected;
      if (item.ts_refuses) {
        expect(run).toThrow(TriageDecisionRefusal);
        return;
      }
      if (expected.raises !== undefined) {
        if (expected.injected === true) {
          // A repository failure Python does not catch propagates unchanged.
          let caught: unknown;
          try {
            run();
          } catch (error) {
            caught = error;
          }
          expect(caught).toBeInstanceOf(TriageGitFailure);
          expect((caught as TriageGitFailure).pythonType).toBe(expected.raises);
        } else {
          expect(run).toThrow(TriageDecisionRefusal);
        }
        expect(calls).toEqual(expected.calls);
        return;
      }
      const result = run();
      expect(result.status).toBe(expected.status);
      expect(result.reason).toBe(expected.reason);
      expect(toPlainJson(result.extras)).toEqual(JSON.parse(expected.extras_json as string));
      expect(calls).toEqual(expected.calls);
    });
  }
});
